def main():
    data = urllib.request.urlopen(URL, timeout=30).read().decode('utf-8')
    chunks = re.split(r'(?=^msgid )', data, flags=re.M)
    changed=[]
    for i, chunk in enumerate(chunks):
        if not re.search(r'(?m)^msgstr ""\s*$', chunk) or chunk.lstrip().startswith('#~'):
            continue
        m = re.search(r'(?m)^msgid ("(?:\\.|[^"\\])*")\s*$', chunk)
        if not m: continue
        try: msgid = ast.literal_eval(m.group(1))
        except Exception: continue
        if msgid in T:
            val = T[msgid].replace('\\','\\\\').replace('"','\\"').replace('\n','\\n')
            chunks[i] = re.sub(r'(?m)^msgstr ""\s*$', 'msgstr "'+val+'"', chunk, count=1)
            changed.append(msgid)
    Path('es.po').write_text(''.join(chunks), encoding='utf-8')
    print(f'Generado es.po: {len(changed)} traducciones aplicadas.')
    missing=sorted(set(T)-set(changed))
    if missing:
        print(f'Aviso: {len(missing)} cadenas no se encontraron vacías en la versión actual.')
        for x in missing: print(' - '+x)
if __name__=='__main__': main()
